// Writes the probe tsconfig (checkJs over the files of the six sets) into the scratchpad.
// Usage: node mkprobe.js <repoRoot> <scratchpadDir>
const fs = require('fs')
const path = require('path')

const repo = process.argv[2].replace(/\\/g, '/')
const sp = process.argv[3]
const sets = JSON.parse(fs.readFileSync(path.join(sp, 'sets.json'), 'utf8'))

const files = []
const missing = []
for (const [set, list] of Object.entries(sets)) {
  for (const f of list) {
    const abs = `${repo}/${f}.js`
    if (!fs.existsSync(abs)) missing.push(`${set}: ${f}.js`)
    files.push(abs)
  }
}

const config = {
  extends: `${repo}/tsconfig.check.json`,
  compilerOptions: {
    checkJs: true,
    // the config lives outside the repository, so @types would not be found by walking up from here
    typeRoots: [`${repo}/node_modules/@types`]
  },
  files,
  include: []
}
fs.writeFileSync(path.join(sp, 'tsconfig.probe.json'), JSON.stringify(config, null, 2))
console.log(`files: ${files.length}, missing: ${missing.length}`)
if (missing.length) console.log(missing.join('\n'))

