// Splits the probe output per set file and collects the facts the briefs need.
// Usage: node analyze.js <repoRoot> <scratchpadDir>
const fs = require('fs')
const path = require('path')

const repo = process.argv[2].replace(/\\/g, '/')
const sp = process.argv[3]
const sets = JSON.parse(fs.readFileSync(path.join(sp, 'sets.json'), 'utf8'))

const setOf = {}
for (const [set, list] of Object.entries(sets)) for (const f of list) setOf[`${f}.js`] = set

// ---- probe errors per file
const raw = fs.readFileSync(path.join(sp, 'probe-raw.txt'), 'utf8').split(/\r?\n/)
const errs = {}
let cur = null
for (const line of raw) {
  const m = line.match(/^([^\s(][^(]*)\((\d+),(\d+)\): error (TS\d+): (.*)$/)
  if (m) {
    cur = { file: m[1].replace(/\\/g, '/'), line: +m[2], col: +m[3], code: m[4], msg: m[5], extra: [] }
    ;(errs[cur.file] ||= []).push(cur)
  } else if (cur && /^\s+\S/.test(line)) {
    cur.extra.push(line)
  }
}

// ---- walk the source tree
function walk(dir, out = []) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = `${dir}/${e.name}`
    if (e.isDirectory()) {
      if (e.name === 'node_modules') continue
      walk(p, out)
    } else if (/\.(js|ts)$/.test(e.name)) out.push(p)
  }
  return out
}
const all = [...walk(`${repo}/server`), ...walk(`${repo}/test`), `${repo}/index.js`].map((p) => p.slice(repo.length + 1))

function resolve(from, spec) {
  const base = path.posix.normalize(path.posix.join(path.posix.dirname(from), spec))
  for (const cand of [base, `${base}.js`, `${base}.ts`, `${base}.json`, `${base}/index.js`, `${base}/index.ts`]) {
    if (fs.existsSync(`${repo}/${cand}`) && fs.statSync(`${repo}/${cand}`).isFile()) return cand
  }
  return null
}

const requires = {} // file -> [target]
const importers = {} // target -> [file]
const typeImports = {} // target -> [{from, name}]
const typedefs = {} // file -> [names]
const lines = {}
for (const f of all) {
  const src = fs.readFileSync(`${repo}/${f}`, 'utf8')
  lines[f] = src.split(/\r?\n/).length
  const seen = new Set()
  for (const m of src.matchAll(/require\(\s*['"](\.[^'"]+)['"]\s*\)/g)) {
    const t = resolve(f, m[1])
    if (!t || seen.has(t)) continue
    seen.add(t)
    ;(requires[f] ||= []).push(t)
    ;(importers[t] ||= []).push(f)
  }
  for (const m of src.matchAll(/import\(\s*['"](\.[^'"]+)['"]\s*\)(?:\.([A-Za-z_$][\w$]*))?/g)) {
    const t = resolve(f, m[1])
    if (!t) continue
    ;(typeImports[t] ||= []).push({ from: f, name: m[2] || null })
  }
  const td = [...src.matchAll(/@typedef\s+(?:\{[^\n]*\}\s+)?([A-Za-z_$][\w$]*)/g)].map((m) => m[1])
  const cb = [...src.matchAll(/@callback\s+([A-Za-z_$][\w$]*)/g)].map((m) => m[1])
  if (td.length || cb.length) typedefs[f] = [...new Set([...td, ...cb])]
}

function status(t) {
  if (setOf[t]) return setOf[t]
  if (t.endsWith('.ts')) return 'ts'
  if (t.startsWith('server/libs/')) return 'libs'
  if (t.endsWith('.json')) return 'json'
  return 'js-not-in-run'
}

fs.mkdirSync(path.join(sp, 'probe'), { recursive: true })
let summary = ''
const totals = {}
for (const [set, list] of Object.entries(sets)) {
  fs.mkdirSync(path.join(sp, 'probe', set), { recursive: true })
  summary += `\n================ ${set} ================\n`
  let setErr = 0
  let setLines = 0
  let setAll = ''
  const rows = []
  for (const stem of list) {
    const f = `${stem}.js`
    const e = errs[f] || []
    const codes = {}
    for (const x of e) codes[x.code] = (codes[x.code] || 0) + 1
    const codeStr = Object.entries(codes)
      .sort((a, b) => b[1] - a[1])
      .map(([c, n]) => `${c}x${n}`)
      .join(' ')
    const body = e.map((x) => `${x.file}(${x.line},${x.col}): ${x.code}: ${x.msg}${x.extra.length ? '\n' + x.extra.join('\n') : ''}`).join('\n')
    fs.writeFileSync(path.join(sp, 'probe', set, `${stem.split('/').pop()}.txt`), body + '\n')
    setAll += `\n######## ${f} (${lines[f]} lines, ${e.length} probe errors)\n${body}\n`
    setErr += e.length
    setLines += lines[f]
    const req = (requires[f] || []).map((t) => `${t} [${status(t)}]`)
    const imps = importers[f] || []
    const tImps = (typeImports[f] || []).filter((x) => x.from !== f)
    const tNamed = tImps.filter((x) => x.name && (typedefs[f] || []).includes(x.name))
    const tests = imps.filter((x) => x.startsWith('test/'))
    rows.push({ f, n: e.length, l: lines[f] })
    summary += `\n--- ${f}  lines=${lines[f]}  probeErrors=${e.length}\n`
    summary += `    codes: ${codeStr || '(none)'}\n`
    summary += `    requires: ${req.join(', ') || '(no relative require)'}\n`
    summary += `    required by (${imps.length}): ${imps.join(', ') || '-'}\n`
    if (tests.length) summary += `    TESTS: ${tests.join(', ')}\n`
    if (typedefs[f]) summary += `    typedefs/callbacks defined here: ${typedefs[f].join(', ')}\n`
    if (tNamed.length) summary += `    JSDoc typedef IMPORTERS (become any silently): ${tNamed.map((x) => `${x.from} -> .${x.name}`).join(', ')}\n`
    const tOther = tImps.filter((x) => !tNamed.includes(x))
    if (tOther.length) summary += `    other JSDoc import() refs: ${[...new Set(tOther.map((x) => `${x.from}${x.name ? ' -> .' + x.name : ''}`))].join(', ')}\n`
  }
  fs.writeFileSync(path.join(sp, 'probe', `${set}-all-errors.txt`), setAll)
  totals[set] = { files: list.length, lines: setLines, errors: setErr }
  summary += `\n${set} TOTAL: files=${list.length} lines=${setLines} probeErrors=${setErr}\n`
  summary += `suggested order (fewest errors first): ${rows.sort((a, b) => a.n - b.n || a.l - b.l).map((r) => `${r.f.split('/').pop()}(${r.n}e/${r.l}l)`).join(' > ')}\n`
}
fs.writeFileSync(path.join(sp, 'probe', 'summary.txt'), summary)
console.log(summary)
console.log(JSON.stringify(totals))

