// Creates one scratch folder per set with a private no-emit check config that adds pending.d.ts.
// Usage: node mkscratch.js <repoRoot> <scratchpadDir>
const fs = require('fs')
const path = require('path')

const repo = process.argv[2].replace(/\\/g, '/')
const sp = process.argv[3]

for (let n = 1; n <= 6; n++) {
  const dir = path.join(sp, `set${n}`)
  fs.mkdirSync(dir, { recursive: true })
  const config = {
    extends: `${repo}/tsconfig.check.json`,
    compilerOptions: {
      // this config lives outside the repository, so @types would not be found by walking up from here
      typeRoots: [`${repo}/node_modules/@types`]
    },
    // include and exclude are inherited from tsconfig.server.json; files adds the proposed declarations
    files: ['./pending.d.ts']
  }
  fs.writeFileSync(path.join(dir, 'tsconfig.pending.json'), JSON.stringify(config, null, 2))
  const p = path.join(dir, 'pending.d.ts')
  if (!fs.existsSync(p)) {
    fs.writeFileSync(
      p,
      [
        '// Proposed ambient module declarations for server/types/untypedModules.d.ts.',
        '// The main agent copies them into the repository in step 3.',
        "// Only `declare module '<npm package>' { ... }` blocks. No import or export at the top level of this file.",
        ''
      ].join('\n')
    )
  }
}
console.log('scratch folders ready')

