        if (inner.kind === ts.SyntaxKind.AsExpression && inner.type.getText(sf) === 'unknown') kind = 'BANNED as unknown as'
        if (kind !== 'const') r.casts.push({ line: lineOf(n), kind, type: typeText.replace(/\s+/g, ' ').slice(0, 90), text: lineText(n).slice(0, 160), prev: prevLine(n).slice(0, 160) })
        break
      }
      case ts.SyntaxKind.TypeAssertionExpression:
        r.casts.push({ line: lineOf(n), kind: 'other(angle)', type: n.type.getText(sf), text: lineText(n).slice(0, 160), prev: '' })
        break
      case ts.SyntaxKind.IndexSignature:
        r.indexSigs.push({ line: lineOf(n), text: lineText(n).slice(0, 160), prev: prevLine(n).slice(0, 160) })
        break
      case ts.SyntaxKind.AnyKeyword:
        r.any.push({ line: lineOf(n), text: lineText(n).slice(0, 160) })
        break
      case ts.SyntaxKind.PropertyDeclaration: {
        const mods = (n.modifiers || []).map((m) => m.kind)
        if (!mods.includes(ts.SyntaxKind.DeclareKeyword)) r.plainFields.push({ line: lineOf(n), text: lineText(n).slice(0, 120) })
        break
      }
      case ts.SyntaxKind.ImportDeclaration:
        if (n.importClause && n.importClause.isTypeOnly) r.importTypes.push({ line: lineOf(n), text: lineText(n).slice(0, 200) })
        else r.other.push({ line: lineOf(n), what: 'ES import (not import type)', text: lineText(n).slice(0, 160) })
        break
      case ts.SyntaxKind.EnumDeclaration:
        r.other.push({ line: lineOf(n), what: 'enum', text: lineText(n).slice(0, 160) })
        break
      case ts.SyntaxKind.ExportDeclaration:
      case ts.SyntaxKind.ExportKeyword:
        if (n.kind === ts.SyntaxKind.ExportDeclaration) r.other.push({ line: lineOf(n), what: 'export declaration', text: lineText(n).slice(0, 160) })
        break
      case ts.SyntaxKind.Parameter:
        if ((n.modifiers || []).some((m) => [ts.SyntaxKind.PublicKeyword, ts.SyntaxKind.PrivateKeyword, ts.SyntaxKind.ProtectedKeyword, ts.SyntaxKind.ReadonlyKeyword].includes(m.kind))) r.other.push({ line: lineOf(n), what: 'parameter property', text: lineText(n).slice(0, 160) })
        break
    }
    ts.forEachChild(n, visit)
  }
  visit(sf)
  for (const m of text.matchAll(/@ts-(ignore|nocheck|expect-error)/g)) r.banned.push(m[0])
  return r
}

const total = { files: 0, lines: 0, nonNull: 0, indexSigs: 0, A1: 0, A2: 0, A3: 0, other: 0, any: 0, banned: 0, importTypes: 0 }
for (const [set, list] of Object.entries(sets)) {
  const st = { files: 0, lines: 0, nonNull: 0, indexSigs: 0, A1: 0, A2: 0, A3: 0, other: 0, any: 0, banned: 0, importTypes: 0 }
  console.log(`\n=== ${set}`)
  for (const stem of list) {
    const file = `${repo}/${stem}.ts`
    if (!fs.existsSync(file)) continue
    const r = analyze(file)
    const lines = fs.readFileSync(file, 'utf8').split(/\r?\n/).length - 1
    const c = { A1: 0, A2: 0, A3: 0, other: 0, banned: 0 }
    for (const x of r.casts) {
      if (x.kind.startsWith('BANNED')) c.banned++
      else if (x.kind === 'A1' || x.kind === 'A2' || x.kind === 'A3') c[x.kind]++
      else c.other++
    }
    st.files++
    st.lines += lines
    st.nonNull += r.nonNull.length
    st.indexSigs += r.indexSigs.length
    st.A1 += c.A1
    st.A2 += c.A2
    st.A3 += c.A3
    st.other += c.other
    st.any += r.any.length
    st.banned += c.banned + r.banned.length
    st.importTypes += r.importTypes.length
    const flags = []
    if (r.any.length) flags.push(`ANY x${r.any.length}`)
    if (c.banned || r.banned.length) flags.push(`BANNED x${c.banned + r.banned.length}`)
    if (r.other.length) flags.push(`RUNTIME-CONSTRUCT x${r.other.length}`)
    if (r.plainFields.length) flags.push(`plain-field x${r.plainFields.length}`)
    console.log(`${stem.split('/').pop().padEnd(28)} lines=${String(lines).padStart(4)}  !=${r.nonNull.length}  idx=${r.indexSigs.length}  casts A1=${c.A1} A2=${c.A2} A3=${c.A3} other=${c.other}  importType=${r.importTypes.length}  ${flags.join(' ')}`)
    if (detail) {
      for (const x of r.nonNull) console.log(`    ! L${x.line}: ${x.text.slice(0, 150)}\n         prev: ${x.prev.slice(0, 150)}`)
      for (const x of r.casts) console.log(`    cast[${x.kind}] L${x.line}: as ${x.type}\n         line: ${x.text}\n         prev: ${x.prev}`)
      for (const x of r.indexSigs) console.log(`    idx L${x.line}: ${x.text}\n         prev: ${x.prev}`)
    }
    for (const x of r.any) console.log(`    ANY L${x.line}: ${x.text}`)
    for (const x of r.banned) console.log(`    BANNED comment: ${x}`)
    for (const x of r.other) console.log(`    ${x.what} L${x.line}: ${x.text}`)
    for (const x of r.plainFields) console.log(`    plain field (check against the original) L${x.line}: ${x.text}`)
    if (detail) for (const x of r.importTypes) console.log(`    import type L${x.line}: ${x.text}`)
  }
  console.log(`${set} TOTAL files=${st.files} lines=${st.lines} !=${st.nonNull} idx=${st.indexSigs} casts A1=${st.A1} A2=${st.A2} A3=${st.A3} other=${st.other} importType=${st.importTypes} any=${st.any} banned=${st.banned}`)
  for (const k of Object.keys(total)) total[k] += st[k]
}
console.log(`\nALL SETS files=${total.files} lines=${total.lines} !=${total.nonNull} idx=${total.indexSigs} casts A1=${total.A1} A2=${total.A2} A3=${total.A3} other=${total.other} importType=${total.importTypes} any=${total.any} banned=${total.banned}`)

