// Compares the compiled output of every converted file with the baseline copy.
// Allowed differences: require lines, comments, the position of module.exports, the destructure of an import,
// and the type-only-namespace const of a module that exports an object. Everything else is printed for review.
// Usage: node compare-dist.js <repoRoot> <scratchpadDir> [--all]   (--all also compares the files that were not converted)
const fs = require('fs')
const path = require('path')

const repo = process.argv[2].replace(/\\/g, '/')
const sp = process.argv[3]
const all = process.argv.includes('--all')
const sets = JSON.parse(fs.readFileSync(path.join(sp, 'sets.json'), 'utf8'))
const base = path.join(sp, 'po-s10-baseline')
const dist = `${repo}/dist-server`

// longest-common-subsequence line diff
function diff(a, b) {
  const n = a.length
  const m = b.length
  const dp = Array.from({ length: n + 1 }, () => new Uint32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) for (let j = m - 1; j >= 0; j--) dp[i][j] = a[i] === b[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
  const out = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (a[i] === b[j]) {
      i++
      j++
    } else if (dp[i + 1][j] >= dp[i][j + 1]) out.push({ s: '-', l: a[i], n: ++i })
    else out.push({ s: '+', l: b[j], n: ++j })
  }
  while (i < n) out.push({ s: '-', l: a[i], n: ++i })
  while (j < m) out.push({ s: '+', l: b[j], n: ++j })
  return out
}

function classify(line) {
  const t = line.trim()
  if (t === '') return 'blank'
  if (/^(\/\/|\/\*|\*\/|\*)/.test(t)) return 'comment'
  if (/\brequire\(/.test(t)) return 'require'
  if (/^module\.exports\s*=/.test(t)) return 'module.exports'
  if (/^const \{[^}]*\} = [A-Za-z_$][\w$]*;$/.test(t)) return 'destructure'
  if (t === '"use strict";') return 'use strict'
  return 'OTHER'
}

function norm(file) {
  return fs
    .readFileSync(file, 'utf8')
    .split(/\r?\n/)
    .map((l) => l.replace(/\s+$/, ''))
}

function walk(dir, out = []) {
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const p = path.join(dir, e.name)
    if (e.isDirectory()) walk(p, out)
    else if (e.name.endsWith('.js')) out.push(p)
  }
  return out
}

let reviewTotal = 0
const summary = []
for (const [set, list] of Object.entries(sets)) {
  for (const stem of list) {
    if (!fs.existsSync(`${repo}/${stem}.ts`)) continue
    const a = path.join(base, `${stem}.js`)
    const b = `${dist}/${stem}.js`
    if (!fs.existsSync(b)) {
      console.log(`!! ${set} ${stem}: no compiled file`)
      reviewTotal++
      continue
    }
    const d = diff(norm(a), norm(b))
    const counts = {}
    const other = []
    for (const x of d) {
      const c = classify(x.l)
      counts[c] = (counts[c] || 0) + 1
      if (c === 'OTHER') other.push(x)
    }
    const c = Object.entries(counts)
      .map(([k, v]) => `${k}=${v}`)
      .join(' ')
    summary.push(`${set} ${stem.padEnd(48)} ${other.length ? 'REVIEW' : 'ok    '} ${c}`)
    if (other.length) {
      reviewTotal += other.length
      console.log(`\n--- ${set} ${stem}: ${other.length} line(s) to review`)
      for (const x of other.slice(0, 60)) console.log(`  ${x.s}${String(x.n).padStart(4)}: ${x.l.slice(0, 200)}`)
      if (other.length > 60) console.log(`  ... ${other.length - 60} more`)
    }
  }
}
console.log('\n===== summary of converted files =====')
console.log(summary.join('\n'))

if (all) {
  // every other compiled file must be byte-identical to the baseline
  const converted = new Set()
  for (const list of Object.values(sets)) for (const stem of list) if (fs.existsSync(`${repo}/${stem}.ts`)) converted.add(stem.replace(/\//g, path.sep) + '.js')
  let same = 0
  const changed = []
  for (const f of walk(base)) {
    const rel = path.relative(base, f)
    if (converted.has(rel)) continue
    const g = path.join(dist, rel)
    if (!fs.existsSync(g)) {
      changed.push(`${rel} (missing in dist-server)`)
      continue
    }
    if (fs.readFileSync(f, 'utf8') === fs.readFileSync(g, 'utf8')) same++
    else changed.push(rel)
  }
  const extra = walk(dist).map((f) => path.relative(dist, f)).filter((rel) => !fs.existsSync(path.join(base, rel)))
  console.log(`\n===== files that were not converted: ${same} identical, ${changed.length} changed, ${extra.length} new =====`)
  for (const c of changed) console.log(`  CHANGED ${c}`)
  for (const c of extra) console.log(`  NEW ${c}`)
}
console.log(`\nlines to review: ${reviewTotal}`)

