// Runs the whole-tree no-emit check once and groups the errors: per set, and files outside all sets.
// Usage: node snapshot.js <repoRoot> <scratchpadDir> <label> [--set-detail]
const fs = require('fs')
const path = require('path')
const cp = require('child_process')

const repo = process.argv[2].replace(/\\/g, '/')
const sp = process.argv[3]
const label = process.argv[4] || 'snap'
const setDetail = process.argv.includes('--set-detail')
const sets = JSON.parse(fs.readFileSync(path.join(sp, 'sets.json'), 'utf8'))
const setOf = {}
for (const [set, list] of Object.entries(sets)) for (const f of list) setOf[f] = set

const r = cp.spawnSync('npx', ['tsc', '-p', 'tsconfig.check.json', '--pretty', 'false'], { cwd: repo, encoding: 'utf8', shell: true, maxBuffer: 1 << 28 })
const raw = (r.stdout || '') + (r.stderr || '')
fs.mkdirSync(path.join(sp, 'snapshots'), { recursive: true })
fs.writeFileSync(path.join(sp, 'snapshots', `${label}.txt`), raw)

const perFile = {}
let cur = null
for (const line of raw.split(/\r?\n/)) {
  const m = line.match(/^([^\s(][^(]*)\((\d+),(\d+)\): error (TS\d+): (.*)$/)
  if (m) {
    cur = { file: m[1].replace(/\\/g, '/'), line: +m[2], code: m[4], msg: m[5], extra: [] }
    ;(perFile[cur.file] ||= []).push(cur)
  } else if (cur && /^\s+\S/.test(line)) cur.extra.push(line.trim())
  else if (line.trim() && !m) (perFile['(other output)'] ||= []).push({ line: 0, code: '', msg: line.trim(), extra: [] })
}

const bySet = {}
const outside = []
for (const [file, list] of Object.entries(perFile)) {
  const stem = file.replace(/\.(ts|js)$/, '')
  const set = setOf[stem]
  if (set) (bySet[set] ||= []).push([file, list])
  else outside.push([file, list])
}
console.log(`snapshot ${label}: tsc exit ${r.status}, ${Object.values(perFile).reduce((a, l) => a + l.length, 0)} errors in ${Object.keys(perFile).length} files`)
for (const set of Object.keys(sets)) {
  const files = bySet[set] || []
  console.log(`  ${set}: ${files.map(([f, l]) => `${f.split('/').pop()}(${l.length})`).join(' ') || 'no errors'}`)
  if (setDetail) for (const [f, l] of files) for (const e of l.slice(0, 12)) console.log(`      ${f}(${e.line}): ${e.code}: ${e.msg.slice(0, 230)}`)
}
console.log(`  OUTSIDE THE SETS: ${outside.length ? '' : 'no errors'}`)
for (const [f, l] of outside) {
  console.log(`    ${f}: ${l.length} error(s)`)
  for (const e of l.slice(0, 8)) console.log(`      (${e.line}) ${e.code}: ${e.msg.slice(0, 260)}${e.extra.length ? '\n          ' + e.extra.slice(0, 3).join('\n          ').slice(0, 400) : ''}`)
}

