for(const [s,l] of Object.entries(sets))for(const stem of l){
  if(!fs.existsSync(repo+'/'+stem+'.ts'))continue;n++;
  const a=req(sp+'/po-s10-baseline/'+stem+'.js'),b=req(repo+'/dist-server/'+stem+'.js');
  const gone=a.filter(x=>!b.includes(x)),added=b.filter(x=>!a.includes(x));
  const common=a.filter(x=>b.includes(x)),commonB=b.filter(x=>a.includes(x));
  const sameOrder=JSON.stringify(common)===JSON.stringify(commonB);
  const norm=x=>x.replace(/\/index$/,'');
  const goneReal=gone.filter(x=>!b.map(norm).includes(norm(x))),addedReal=added.filter(x=>!a.map(norm).includes(norm(x)));
  if(goneReal.length||addedReal.length||!sameOrder){changed++;console.log(s,stem,'| no longer required:',JSON.stringify(goneReal),'| newly required:',JSON.stringify(addedReal),'| order kept:',sameOrder)}
}
console.log('converted files:',n,'| files whose set of required modules or their order changed:',changed);
" "$SP" "$R"; echo "== position of module.exports in the 20 compiled files (line / total lines)"; for f in $(node -e "const s=require('$SP/sets.json');for(const l of Object.values(s))for(const x of l)if(require('fs').existsSync('$R/'+x+'.ts'))console.log(x)"); do b=$(grep -nE "^module\.exports\s*=" "$SP/po-s10-baseline/$f.js" | tail -1 | cut -d: -f1); bt=$(wc -l < "$SP/po-s10-baseline/$f.js"); n=$(grep -nE "^module\.exports\s*=" "dist-server/$f.js" | tail -1 | cut -d: -f1); nt=$(wc -l < "dist-server/$f.js"); echo "$(basename $f): before ${b:-none}/$bt  after ${n:-none}/$nt"; done

