// Loads <distRoot>/server/Server.js (the whole server module graph, without starting the server)
// and prints the order in which the compiled modules were first loaded.
// Usage: NODE_PATH=<repo>/node_modules node smoke.js <distRoot> <outFile>
const path = require('path')
const fs = require('fs')

const root = path.resolve(process.argv[2])
const out = process.argv[3]
let error = null
try {
  require(path.join(root, 'server', 'Server.js'))
} catch (e) {
  error = e
}
const order = Object.keys(require.cache)
  .filter((f) => f.startsWith(root + path.sep))
  .map((f) => path.relative(root, f).replace(/\\/g, '/'))
fs.writeFileSync(out, order.join('\n') + '\n')
console.log(`loaded ${order.length} modules from ${path.basename(root)}; error: ${error ? error.message.split('\n')[0] : 'none'}`)
process.exit(0)

